tinycast.eval.metrics.pinball_loss.code:
def pinball_loss(y: np.ndarray, q: np.ndarray, levels: Sequence[float]) -> np.ndarray:
    """Element-wise pinball loss, shape (B, K, H). y: (B, H), q: (B, K, H)."""
    tau = np.asarray(levels, dtype=np.float64)[None, :, None]
    diff = y[:, None, :].astype(np.float64) - q.astype(np.float64)
    return np.maximum(tau * diff, (tau - 1.0) * diff)

tinycast.eval.metrics.coverage.code:
def coverage(
    y: np.ndarray, q: np.ndarray, levels: Sequence[float], lo: float, hi: float
) -> np.ndarray:
    """Per-series fraction of observed y inside [q_lo, q_hi], shape (B,)."""
    i_lo, i_hi = _level_index(levels, [lo, hi])
    inside = (y >= q[:, i_lo, :]) & (y <= q[:, i_hi, :])
    mask = ~np.isnan(y)
    return (inside & mask).sum(-1) / np.maximum(mask.sum(-1), 1)

tinycast.eval.metrics.bootstrap_ci.code:
def bootstrap_ci(
    x: np.ndarray,
    stat: str = "geomean",
    n_boot: int = 2000,
    alpha: float = 0.05,
    seed: int = 0,
    groups: np.ndarray | None = None,
) -> tuple[float, float, float]:
    """(point, lo, hi) of `stat` with a percentile bootstrap.

    Without `groups`, resamples items. With `groups` (e.g. the series id of each window),
    resamples whole groups (cluster bootstrap): windows of the same series are correlated
    (overlapping targets, shared regime), so resampling them independently gives CIs that
    are far too narrow.
    """
    x = np.asarray(x, dtype=np.float64)
    keep = np.isfinite(x) & ((x > 0) if stat == "geomean" else True)
    x = x[keep]
    g = None if groups is None else np.asarray(groups)[keep]
    if stat == "geomean":
        f = geometric_mean
    elif stat == "mean":

        def f(v: np.ndarray) -> float:
            return float(np.mean(v))
    else:
        raise ValueError(stat)
    if x.size == 0:
        return (float("nan"),) * 3
    rng = np.random.default_rng(seed)
    if g is None:
        idx = rng.integers(0, x.size, size=(n_boot, x.size))
        boots = np.array([f(x[i]) for i in idx])
    else:
        members = [np.flatnonzero(g == u) for u in np.unique(g)]
        k = len(members)
        boots = np.array(
            [
                f(x[np.concatenate([members[j] for j in rng.integers(0, k, k)])])
                for _ in range(n_boot)
            ]
        )
    return f(x), float(np.quantile(boots, alpha / 2)), float(np.quantile(boots, 1 - alpha / 2))

tinycast.models.student._asinh.code:
def _asinh(z: torch.Tensor) -> torch.Tensor:
    a = z.abs()
    return torch.sign(z) * torch.log(a + torch.sqrt(a * a + 1.0))

tinycast.distill.losses.level_mass.code:
def level_mass(levels: Sequence[float], device=None) -> torch.Tensor:
    """Probability mass of each level (midpoint rule), sums to 1."""
    lv = torch.tensor(list(levels), dtype=torch.float32, device=device)
    edges = torch.cat([lv.new_zeros(1), (lv[1:] + lv[:-1]) / 2, lv.new_ones(1)])
    return edges.diff()

tinycast.distill.losses.mixed_objective.code:
def mixed_objective(l_gt: torch.Tensor, l_kd: torch.Tensor | None, alpha: float) -> torch.Tensor:
    """L = (1 - alpha) L_gt + alpha L_kd."""
    if alpha == 0 or l_kd is None:
        if alpha > 0:
            raise ValueError("alpha > 0 but no KD loss (no teacher cache?)")
        return l_gt
    return (1 - alpha) * l_gt + alpha * l_kd

tinycast.distill.train.scaled_targets.code:
def scaled_targets(
    model: Student, y: torch.Tensor, loc: torch.Tensor, scale: torch.Tensor
) -> torch.Tensor:
    """Ground truth / teacher values in the student's scaled space (context statistics only)."""
    y0 = torch.nan_to_num(y, nan=0.0)
    return model.scaler.scale(
        y0, loc if y.dim() == 2 else loc[..., None], scale if y.dim() == 2 else scale[..., None]
    )

tinycast.distill.train.lr_at.code:
def lr_at(step: int, base: float, warmup: int, total: int) -> float:
    """Linear warm-up then cosine decay to 10% of base."""
    if step < warmup:
        return base * (step + 1) / warmup
    p = (step - warmup) / max(1, total - warmup)
    return base * (0.1 + 0.9 * 0.5 * (1 + math.cos(math.pi * min(p, 1.0))))

tinycast.data.synthetic.kernel_synth.code:
def kernel_synth(rng: np.random.Generator, n: int, max_kernels: int = 4) -> np.ndarray:
    t = np.linspace(0, 1, n)
    K = _kernel(rng, t)
    for _ in range(rng.integers(0, max_kernels)):
        K2 = _kernel(rng, t)
        K = K + K2 if rng.uniform() < 0.5 else K * K2
    K = K + 1e-6 * np.eye(n)
    L = np.linalg.cholesky(K + 1e-4 * np.trace(K) / n * np.eye(n))
    x = L @ rng.standard_normal(n)
    return x * rng.uniform(0.5, 5) + rng.uniform(-2, 20)
